                <Line>
                    <Word>
                        <Bold />
                        Symbolic lifting
                    </Word>: <Word>
                        <Verbatim />
                        (x,y) -&gt; t =|&gt; ((x,y)) -&gt; (t)
                    </Word>
                </Line>
                <Line>
